<!doctype html><html lang="es"><head><meta charset="utf-8"><title><?= e($q['codigo']) ?></title>
<style>body{font-family:Arial,sans-serif;font-size:13px;max-width:760px;margin:20px auto;color:#111}.h{display:flex;justify-content:space-between;gap:16px}.box{border:2px solid #0ea5e9;color:#0369a1;padding:10px 18px;text-align:center;border-radius:6px}.box b{display:block;font-size:16px}
table{width:100%;border-collapse:collapse;margin-top:12px}th{background:#e0f2fe;text-align:left}td,th{padding:6px 8px;border:1px solid #cbd5e1}.r{text-align:right}.tot td{border:0}img{max-height:60px}@media print{@page{margin:12mm}}</style></head>
<body onload="window.print()"><div class="h"><div><?php if (!empty($emp['logo'])): ?><img src="<?= asset('uploads/' . e($emp['logo'])) ?>"><br><?php endif; ?><b style="font-size:17px"><?= e($emp['nombre']) ?></b><br><?= e($emp['direccion'] ?? '') ?><br><?= e($emp['telefono'] ?? '') ?></div>
<div class="box">COTIZACIÓN<b><?= e($q['codigo']) ?></b><?= fdate($q['created_at']) ?></div></div>
<p><b>Cliente:</b> <?= e($q['nombre'] ?? '-') ?> · <?= e($q['telefono'] ?? '') ?><br><b>Vehículo:</b> <?= e($q['placa'] ?? '-') ?> <?= e($q['tipo_veh'] ?? '') ?><?= $q['vence'] ? '<br><b>Válida hasta:</b> ' . fdate($q['vence']) : '' ?></p>
<table><thead><tr><th>Descripción</th><th class="r">Cant.</th><th class="r">P. unit.</th><th class="r">Importe</th></tr></thead><tbody><?php foreach ($q['items'] as $d): ?><tr><td><?= e($d['descripcion']) ?></td><td class="r"><?= num($d['cantidad'], 0) ?></td><td class="r"><?= num($d['precio']) ?></td><td class="r"><?= num($d['subtotal']) ?></td></tr><?php endforeach; ?></tbody></table>
<table class="tot" style="width:280px;margin-left:auto"><tr><td>Subtotal</td><td class="r"><?= money($q['subtotal']) ?></td></tr><?php if ($q['descuento'] > 0): ?><tr><td>Descuento</td><td class="r">- <?= money($q['descuento']) ?></td></tr><?php endif; ?><tr><td><?= e($emp['impuesto_nombre']) ?></td><td class="r"><?= money($q['impuesto']) ?></td></tr><tr><td><b>TOTAL</b></td><td class="r"><b><?= money($q['total']) ?></b></td></tr></table>
<?php if ($q['observaciones']): ?><p><b>Observaciones:</b> <?= e($q['observaciones']) ?></p><?php endif; ?><p style="font-size:11px;color:#555;margin-top:24px">Precios sujetos a variación según el estado del vehículo. <?= e($emp['pie_ticket'] ?? '') ?></p></body></html>
